//! Removing the Regions from a Mapping gives what C's `astRemoveRegions`
//! gives: each class removes them from its own components (cmpmap.c,
//! tranmap.c, ratemap.c, normmap.c, cmpframe.c, region.c `RemoveRegions`),
//! a series CmpMap drops a component that became a UnitMap, and a parallel
//! CmpMap or a TranMap of two UnitMaps becomes one UnitMap. Each result's
//! dump must equal C's.
//!
//! `remove_regions_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/remove_regions_probe.c`, against C with the
//! TranMap dimensionality fix (upstream 80d66b0a).

use crate::common::native_dump;
// Generated; formatted by its generator rather than rustfmt.
#[rustfmt::skip]
#[path = "remove_regions_oracle/cases.rs"]
mod cases;

use starlink_ast::regions::remove_regions;
use starlink_ast::{AnyObject, from_native_string};

fn text(lines: &[&str]) -> String {
    let mut s = lines.join("\n");
    s.push('\n');
    s
}

#[test]
fn removing_regions_matches_the_c_library() {
    let mut failures = Vec::new();
    for &(name, input, want) in cases::CASES {
        let obj = from_native_string(&text(input)).unwrap();
        let map = obj.as_mapping().expect("a Mapping");
        let result = remove_regions(map);
        let got =
            native_dump(&AnyObject::from_mapping(result.as_ref()).expect("a known class")).unwrap();
        if got != text(want) {
            failures.push(format!("{name}:\n{got}\nC gives:\n{}", text(want)));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}
